import{_ as e,o as a,c as r,a2 as i}from"./chunks/framework.CfwCq2QB.js";const o="/dev-go-docs/shots/0.2.3/manual/github.png",p=JSON.parse('{"title":"GitHub 增强","description":"","frontmatter":{},"headers":[],"relativePath":"features/github.md","filePath":"features/github.md"}'),d={name:"features/github.md"};function s(h,t,u,b,n,c){return a(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="github-增强" tabindex="-1">GitHub 增强 <a class="header-anchor" href="#github-增强" aria-label="Permalink to &quot;GitHub 增强&quot;">​</a></h1><p>一句话：GitHub 代码页悬浮按钮（在线编辑、DeepWiki、回到顶部），按 <code>,</code> 一键用 github1s 打开；GitHub 代码区不会被浏览器自动翻译干扰。</p><p>在设置页「网页增强 → GitHub 增强」可整体开关。</p><h2 id="悬浮按钮" tabindex="-1">悬浮按钮 <a class="header-anchor" href="#悬浮按钮" aria-label="Permalink to &quot;悬浮按钮&quot;">​</a></h2><p>打开任意仓库的代码页（仓库首页、目录、文件页）时，页面右下角出现一列悬浮按钮：</p><table tabindex="0"><thead><tr><th>按钮</th><th>作用</th></tr></thead><tbody><tr><td>在线编辑</td><td>在 <a href="https://github1s.com" target="_blank" rel="noreferrer">github1s</a> 打开当前仓库和路径——VS Code 界面的网页版代码浏览，比 github.dev 加载更快</td></tr><tr><td>DeepWiki</td><td>在 <a href="https://deepwiki.com" target="_blank" rel="noreferrer">deepwiki.com</a> 打开当前仓库的 AI 生成文档：架构、模块讲解，快速了解陌生项目</td></tr><tr><td>回到顶部</td><td>页面滚过一段距离后才出现</td></tr></tbody></table><p>仓库的 Issues、Pull Request、Actions 等子页面不显示按钮，不干扰正常浏览。</p><img src="'+o+'" alt="GitHub 代码页右侧的悬浮按钮：在线编辑、DeepWiki，页面下滚后出现回到顶部"><h2 id="快捷键" tabindex="-1">快捷键 <code>,</code> <a class="header-anchor" href="#快捷键" aria-label="Permalink to &quot;快捷键 `,`&quot;">​</a></h2><p>在 GitHub 代码页的<strong>非输入框</strong>里按一下 <code>,</code>，直接用 github1s 打开当前仓库路径，和「在线编辑」按钮等效。（这也是 GitHub 官方 <code>.</code> 打开 github.dev 的习惯用法，<code>,</code> 对应更快的 github1s。）</p><h2 id="代码区防误翻译" tabindex="-1">代码区防误翻译 <a class="header-anchor" href="#代码区防误翻译" aria-label="Permalink to &quot;代码区防误翻译&quot;">​</a></h2><p>用浏览器自带翻译或 DevGo 整页翻译看外文 README 时，代码块容易被一起翻译弄坏。DevGo 会给 GitHub 代码区加上「不应翻译」标记，译文只作用于自然语言部分，代码保持原样。</p>',12)])])}const _=e(d,[["render",s]]);export{p as __pageData,_ as default};
